def match(orders):
    """
    Simulates a price-time priority limit order book.

    Returns trades in execution order: [buy_id, sell_id, price, qty]
    """
    trades = []
    buy_book = []  # [(price, arrival_time, id, qty)]
    sell_book = []  # [(price, arrival_time, id, qty)]
    resting_orders = {}  # {id: (side, price, arrival_time, remaining_qty)}
    arrival_time = 0

    for order in orders:
        arrival_time += 1

        if order[0] == 'cancel':
            order_id = order[1]
            if order_id in resting_orders:
                side, price, arr_time, qty = resting_orders[order_id]
                del resting_orders[order_id]
                # Remove from order book
                if side == 'buy':
                    buy_book[:] = [o for o in buy_book if o[2] != order_id]
                else:
                    sell_book[:] = [o for o in sell_book if o[2] != order_id]

        elif order[0] == 'limit':
            _, order_id, side, price, qty = order
            remaining_qty = qty

            if side == 'buy':
                # Match against sell book (lowest price first, then earliest)
                sell_book.sort(key=lambda x: (x[0], x[1]))
                i = 0
                while i < len(sell_book) and remaining_qty > 0:
                    sell_price, sell_arr_time, sell_id, sell_qty = sell_book[i]
                    if sell_price <= price:
                        trade_qty = min(remaining_qty, sell_qty)
                        trades.append([order_id, sell_id, sell_price, trade_qty])
                        remaining_qty -= trade_qty
                        sell_book[i] = (sell_price, sell_arr_time, sell_id, sell_qty - trade_qty)
